(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-944":{scenario:{company:"Thanh Lam Paper Mill JSC",supervisor:{name:"Đỗ Minh Khôi",role:{vi:"Trưởng đoàn kiểm toán năng lượng",en:"Lead Energy Auditor"}},ref_code:"EA-3105",title:{vi:"Đo thật. Tính đúng. Kiểm chứng được.",en:"Measure it. Calculate it. Verify it."},brief:{vi:"Bạn hoàn thiện báo cáo kiểm toán năng lượng EA-3105 cho giải pháp lắp biến tần (VSD) trên bơm nước làm mát 75 kW. Máy phân tích công suất ghi: trước cải tạo trung bình 62 kW, khi chạy thử biến tần 41 kW; bơm chạy 6000 giờ/năm, lưu lượng và giờ chạy đổi theo ca. Tiết kiệm dự kiến chỉ khoảng 3% điện năng toàn nhà máy. Sửa phương án đo lường và kiểm chứng (M&V) và mức tiết kiệm điện năm, rồi lập báo cáo có căn cứ.",en:"You are finalising energy audit report EA-3105 for a variable speed drive (VSD) on a 75 kW cooling water pump. The power analyser shows 62 kW average before the retrofit and 41 kW during the VSD trial; the pump runs 6000 hours per year and both flow and running hours vary by shift. Expected savings are only about 3% of plant electricity. Correct the measurement and verification (M&V) option and the annual savings, then write an evidence-based report."},reference_title:{vi:"Hồ sơ đo hiện trường & kế hoạch M&V đã duyệt · EA-3105",en:"Approved field measurement file & M&V plan · EA-3105"},fields:[{id:"MV_OPTION",label:{vi:"Phương án M&V theo IPMVP",en:"IPMVP M&V option"},initial:"IPMVP-A",expected:"IPMVP-B",choices:["IPMVP-A","IPMVP-B","IPMVP-C"],reference:"Kế hoạch đo lường & kiểm chứng (M&V)",hint:{vi:"Công suất và giờ chạy đều biến động thì phải đo mọi thông số trong ranh giới cách ly; tiết kiệm nhỏ so với toàn nhà máy thì không dùng đồng hồ tổng.",en:"When both power and hours vary, measure every parameter inside the retrofit boundary; small savings versus the whole plant rule out the main meter."}},{id:"SAVING_KWH",label:{vi:"Tiết kiệm điện năm (kWh)",en:"Annual electricity savings (kWh)"},initial:"204000",expected:"126000",reference:"Biên bản đo công suất trước và sau",ref_value:{vi:"Nhãn động cơ 75 kW; đo trung bình trước 62 kW, sau 41 kW; 6000 giờ/năm",en:"Motor nameplate 75 kW; measured average 62 kW before, 41 kW after; 6000 h/year"},hint:{vi:"Tính tiết kiệm từ công suất đo thực tế, không lấy công suất định mức ghi trên nhãn động cơ.",en:"Calculate savings from measured power, never from the rated power on the motor nameplate."}}],sop32:{vi:"Tiết kiệm điện năm (kWh) = (công suất đo trung bình trước cải tạo - công suất đo sau cải tạo) x số giờ vận hành năm; không dùng công suất định mức trên nhãn động cơ.",en:"Annual savings (kWh) = (measured average power before retrofit - measured power after retrofit) x annual operating hours; never use the motor nameplate rating."},context:{label:"BÁO CÁO NHÁP / EA-3105",metrics:[{label:{vi:"Công suất đo trước",en:"Measured power before"},value:"62 kW"},{label:{vi:"Công suất đo sau",en:"Measured power after"},value:"41 kW"},{label:{vi:"Giờ vận hành năm",en:"Annual operating hours"},value:"6000 h"}]},crisis:{vi:"Giám đốc nhà máy nhắn: “Cứ ghi 204000 kWh theo công suất nhãn đi, hồ sơ vay tín dụng xanh cần tiết kiệm trên 150000 kWh mới đạt. Ngân hàng chỉ xem tổng số, sáng mai phải nộp.”",en:"The plant director messages you: “Just write 204000 kWh using the nameplate power, the green loan file needs more than 150000 kWh of savings to qualify. The bank only looks at the total and it is due tomorrow morning.”"},options:{safe:{vi:"Giữ kết quả đo 126000 kWh, báo trưởng đoàn kiểm toán, đề xuất bổ sung giải pháp có căn cứ (động cơ hiệu suất cao, giảm áp hệ thống) để hồ sơ đạt ngưỡng một cách trung thực.",en:"Keep the measured 126000 kWh, inform the lead auditor and propose additional evidence-based measures (high-efficiency motor, lower system pressure) so the file can qualify honestly."},shortcut:{vi:"Ghi 204000 kWh theo công suất nhãn để kịp hồ sơ vay, sau này kiểm chứng lại sau.",en:"Write 204000 kWh from the nameplate to meet the loan deadline and verify later."},wait:{vi:"Tạm không nộp báo cáo và chờ giám đốc nhà máy tự quyết định số liệu.",en:"Hold the report and wait for the plant director to decide the figures."}},questions:{vi:["Vì sao chọn IPMVP-B thay vì IPMVP-A hay IPMVP-C? Dữ liệu đo nào chứng minh lựa chọn của bạn?","Trình bày cách tính 126000 kWh và rủi ro pháp lý, tài chính nếu khai tiết kiệm theo công suất nhãn động cơ."],en:["Why did you choose IPMVP-B instead of IPMVP-A or IPMVP-C? Which measurements support your choice?","Explain how you calculated 126000 kWh and the legal and financial risks of reporting savings from the motor nameplate."]},hints:{vi:["Đặt kế hoạch M&V cạnh biên bản đo và đánh dấu thông số nào đang biến động theo ca.","Lấy hiệu công suất đo trước và sau nhân với giờ vận hành theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi yêu cầu nâng số tiết kiệm phải báo trưởng đoàn, không được sửa số đo."],en:["Place the M&V plan next to the measurement record and flag which parameters vary by shift.","Multiply the measured power difference by operating hours as set out in SOP 3.2.","Re-read SOP 4.2: any request to inflate savings must go to the lead auditor; measured data is never altered."]}},learning:{summary:{vi:"Kiểm toán viên năng lượng khảo sát, đo đạc và phân tích cách nhà máy, tòa nhà sử dụng điện, nhiệt và nhiên liệu để tìm tổn thất, đề xuất giải pháp tiết kiệm có tính toán kinh tế kèm kế hoạch đo lường, kiểm chứng. Nghề đòi hỏi kỹ năng đo hiện trường, hiểu hệ thống động lực (bơm, quạt, máy nén, lò hơi, điều hòa, chiếu sáng), phân tích số liệu và giữ tính độc lập, trung thực trong báo cáo.",en:"An energy auditor surveys, measures and analyses how plants and buildings use electricity, heat and fuel to find losses, then proposes savings measures with economic analysis and a measurement and verification plan. The role requires field measurement skills, knowledge of utility systems (pumps, fans, compressors, boilers, HVAC, lighting), data analysis and strict independence and honesty in reporting."},responsibilities:{vi:["Thu thập hóa đơn năng lượng, sơ đồ hệ thống và lập đường cơ sở tiêu thụ năng lượng.","Đo đạc hiện trường: công suất, chất lượng điện, lưu lượng, nhiệt độ, khí thải lò hơi.","Phân tích tổn thất và đề xuất giải pháp tiết kiệm (ECM) kèm chi phí, tiết kiệm, thời gian hoàn vốn.","Xây dựng kế hoạch đo lường và kiểm chứng (M&V) cho từng giải pháp.","Lập báo cáo kiểm toán năng lượng, trình bày với ban lãnh đạo và theo dõi kết quả triển khai."],en:["Collect energy bills and system diagrams and build the energy consumption baseline.","Take field measurements: power, power quality, flow, temperature and boiler flue gas.","Analyse losses and propose energy conservation measures (ECMs) with cost, savings and payback.","Design a measurement and verification (M&V) plan for each measure.","Write the energy audit report, present it to management and follow up on implementation."]},competencies:[{name:{vi:"Đo đạc hiện trường",en:"Field measurement"},desc:{vi:"Lắp đặt an toàn thiết bị phân tích công suất, data logger, camera nhiệt và đọc đúng số liệu.",en:"Safely install power analysers, data loggers and thermal cameras and read the data correctly."}},{name:{vi:"Phân tích hệ thống động lực",en:"Utility system analysis"},desc:{vi:"Hiểu đặc tính bơm, quạt, khí nén, hơi, lạnh và định luật tương tự để ước tính tiềm năng tiết kiệm.",en:"Understand pump, fan, compressed air, steam and chiller behaviour and the affinity laws to estimate savings."}},{name:{vi:"Đánh giá kinh tế giải pháp",en:"Economic appraisal"},desc:{vi:"Tính thời gian hoàn vốn, NPV, IRR và xếp hạng giải pháp theo hiệu quả đầu tư.",en:"Calculate payback, NPV and IRR and rank measures by investment return."}},{name:{vi:"Đo lường & kiểm chứng",en:"Measurement & verification"},desc:{vi:"Chọn phương án IPMVP phù hợp, điều chỉnh đường cơ sở theo sản lượng, thời tiết.",en:"Select the right IPMVP option and adjust the baseline for production and weather."}},{name:{vi:"Độc lập & trung thực",en:"Independence & integrity"},desc:{vi:"Báo cáo đúng số đo dù khách hàng muốn kết quả đẹp hơn để vay vốn hay nhận ưu đãi.",en:"Report measured results even when the client wants better numbers for loans or incentives."}}],knowledge:{vi:["Luật Sử dụng năng lượng tiết kiệm và hiệu quả số 50/2010/QH12 và các văn bản sửa đổi, hướng dẫn về cơ sở sử dụng năng lượng trọng điểm và kiểm toán năng lượng định kỳ.","ISO 50001 về hệ thống quản lý năng lượng và ISO 50002 về yêu cầu đối với kiểm toán năng lượng.","Giao thức quốc tế đo lường và kiểm chứng hiệu quả (IPMVP) với 4 phương án A, B, C, D.","Định luật tương tự của bơm, quạt: lưu lượng tỷ lệ tốc độ, cột áp tỷ lệ bình phương, công suất tỷ lệ lập phương tốc độ.","Quy đổi năng lượng về tấn dầu tương đương (TOE), suất tiêu hao năng lượng và hệ số phát thải khí nhà kính."],en:["Law on Economical and Efficient Use of Energy No. 50/2010/QH12 and its amending and guiding documents on designated energy users and periodic energy audits.","ISO 50001 on energy management systems and ISO 50002 on energy audit requirements.","International Performance Measurement and Verification Protocol (IPMVP) with options A, B, C and D.","Pump and fan affinity laws: flow varies with speed, head with speed squared and power with speed cubed.","Conversion to tonnes of oil equivalent (TOE), specific energy consumption and greenhouse gas emission factors."]},tools:["Máy phân tích công suất & chất lượng điện","Camera nhiệt hồng ngoại","Máy phân tích khí thải lò hơi","Đồng hồ đo lưu lượng siêu âm","Bộ ghi dữ liệu (data logger)","Bảng tính phân tích kinh tế ECM"],kpis:{vi:["Độ lệch giữa tiết kiệm kiểm chứng và tiết kiệm dự báo (mục tiêu dưới 10%).","Tỷ lệ giải pháp đề xuất được doanh nghiệp triển khai.","Thời gian hoàn thành báo cáo sau khảo sát hiện trường.","Số sai sót số liệu phát hiện khi thẩm định báo cáo (mục tiêu bằng 0)."],en:["Gap between verified and predicted savings (target below 10%).","Share of proposed measures implemented by the client.","Report turnaround time after the site survey.","Data errors found during report review (target zero)."]},day:[{time:"07:30",vi:"Họp an toàn với nhà máy, nhận giấy phép làm việc khu vực trạm bơm và tủ điện.",en:"Safety briefing with the plant and work permit for the pump house and switchboards."},{time:"09:00",vi:"Lắp máy phân tích công suất và data logger trên tủ điện bơm, kiểm tra kẹp dòng.",en:"Install the power analyser and data logger on the pump panel and check the current clamps."},{time:"11:00",vi:"Đo khí thải lò hơi, quét camera nhiệt đường ống hơi tìm điểm mất nhiệt.",en:"Measure boiler flue gas and scan steam pipes with a thermal camera for heat losses."},{time:"14:00",vi:"Tải dữ liệu đo, lập đường cơ sở và tính tiết kiệm cho từng giải pháp.",en:"Download the logged data, build the baseline and calculate savings per measure."},{time:"16:30",vi:"Tính thời gian hoàn vốn, viết kế hoạch M&V và cập nhật báo cáo nháp.",en:"Calculate payback, write the M&V plan and update the draft report."}],mistakes:{vi:["Dùng công suất định mức trên nhãn thay cho công suất đo thực tế, làm thổi phồng tiết kiệm.","Cộng dồn tiết kiệm của các giải pháp tương tác nhau (biến tần và động cơ mới) như thể độc lập.","Chọn phương án M&V không phù hợp với mức biến động của phụ tải và quy mô tiết kiệm."],en:["Using nameplate power instead of measured power, which inflates savings.","Adding up savings from interacting measures (VSD and new motor) as if they were independent.","Choosing an M&V option that does not match load variability and the size of the savings."]},career:[{vi:"Kỹ thuật viên đo đạc năng lượng",en:"Energy measurement technician"},{vi:"Kiểm toán viên năng lượng",en:"Energy auditor"},{vi:"Trưởng đoàn kiểm toán năng lượng",en:"Lead energy auditor"},{vi:"Chuyên gia tư vấn quản lý năng lượng & ESG",en:"Energy management & ESG consultant"}],glossary:[{term:"ECM",vi:"Giải pháp tiết kiệm năng lượng (Energy Conservation Measure) được đề xuất trong báo cáo kiểm toán.",en:"Energy Conservation Measure proposed in an energy audit report."},{term:"IPMVP",vi:"Giao thức quốc tế đo lường và kiểm chứng hiệu quả, gồm 4 phương án A, B, C, D.",en:"International Performance Measurement and Verification Protocol with options A, B, C and D."},{term:"TOE",vi:"Tấn dầu tương đương, đơn vị quy đổi chung để so sánh các dạng năng lượng.",en:"Tonne of oil equivalent, a common unit for comparing energy forms."},{term:"Baseline",vi:"Đường cơ sở: mức tiêu thụ năng lượng trước cải tạo, dùng để so sánh và tính tiết kiệm.",en:"Energy use before the retrofit, used as the reference for calculating savings."},{term:"VSD",vi:"Biến tần điều chỉnh tốc độ động cơ theo nhu cầu thực tế thay cho tiết lưu bằng van.",en:"Variable speed drive that matches motor speed to demand instead of throttling with valves."}],quiz:[{q:{vi:"Bơm ly tâm giảm tốc độ còn 80% nhờ biến tần, công suất trục lý thuyết còn khoảng bao nhiêu?",en:"A centrifugal pump is slowed to 80% speed with a VSD. What is the theoretical shaft power?"},options:{vi:["80%","64%","51%","40%"],en:["80%","64%","51%","40%"]},answer:2,explain:{vi:"Theo định luật tương tự, công suất tỷ lệ lập phương tốc độ: 0.8 x 0.8 x 0.8 = 0.512, khoảng 51%.",en:"Under the affinity laws power varies with speed cubed: 0.8 x 0.8 x 0.8 = 0.512, about 51%."}},{q:{vi:"Phụ tải và giờ chạy đều biến động, tiết kiệm nhỏ so với toàn nhà máy. Nên chọn phương án IPMVP nào?",en:"Load and running hours both vary and savings are small versus the whole plant. Which IPMVP option fits?"},options:{vi:["Phương án A","Phương án B","Phương án C","Không cần M&V"],en:["Option A","Option B","Option C","No M&V needed"]},answer:1,explain:{vi:"Phương án B đo liên tục mọi thông số trong ranh giới cách ly, phù hợp khi phụ tải biến động; phương án C cần tiết kiệm đủ lớn so với đồng hồ tổng.",en:"Option B measures all parameters inside the boundary, suited to variable loads; Option C needs savings large enough to show on the main meter."}},{q:{vi:"Khách hàng đề nghị tăng số tiết kiệm trong báo cáo để đạt điều kiện vay vốn. Bạn làm gì?",en:"The client asks you to raise the savings in the report to qualify for a loan. What do you do?"},options:{vi:["Sửa số theo yêu cầu","Nộp báo cáo nhưng không ký","Bỏ trống mục tiết kiệm","Giữ số đo, báo trưởng đoàn và đề xuất giải pháp bổ sung hợp lệ"],en:["Change the figures as asked","Submit the report unsigned","Leave the savings section blank","Keep measured data, inform the lead auditor and propose valid extra measures"]},answer:3,explain:{vi:"Kiểm toán viên phải độc lập; thổi phồng tiết kiệm là gian lận với ngân hàng và gây rủi ro pháp lý cho cả hai bên.",en:"Auditors must stay independent; inflating savings misleads the bank and creates legal risk for both parties."}},{q:{vi:"Giải pháp đầu tư 480 triệu đồng, tiết kiệm 240 triệu đồng mỗi năm. Thời gian hoàn vốn giản đơn là bao lâu?",en:"A measure costs 480 million VND and saves 240 million VND per year. What is the simple payback?"},options:{vi:["2 năm","0.5 năm","4 năm","20 năm"],en:["2 years","0.5 years","4 years","20 years"]},answer:0,explain:{vi:"Thời gian hoàn vốn giản đơn = vốn đầu tư / tiết kiệm hằng năm = 480 / 240 = 2 năm.",en:"Simple payback = investment / annual savings = 480 / 240 = 2 years."}}],tools_en:["Power & power quality analyzer","Infrared thermal camera","Boiler flue gas analyzer","Ultrasonic flow meter","Data logger","ECM economic analysis spreadsheet"]}}})})(window.KKR);
